import { getMetaContent } from "helpers/meta_helpers"

const LOCALE = "en-US"
const RELATIVE_DAYS_WINDOW = 7

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

// Snap a timestamp to midnight using the timezone the server rendered with (the
// `timezone` meta tag), so client day boundaries match the server's instead of
// following the browser's resolved timezone, which can differ in a PWA.
function datePartsInTimezone(date) {
  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

let dateFormatterCache
let dateFormatterTimezone

function dateFormatter() {
  const timezone = getMetaContent("timezone")

  if (!dateFormatterCache || dateFormatterTimezone !== timezone) {
    dateFormatterTimezone = timezone
    dateFormatterCache = buildDateFormatter(timezone)
  }

  return dateFormatterCache
}

function buildDateFormatter(timezone) {
  const options = { year: "numeric", month: "2-digit", day: "2-digit" }

  try {
    return new Intl.DateTimeFormat(LOCALE, { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat(LOCALE, options)
  }
}

export function parseTimestamp(value) {
  if (!value) return null

  const dateOnlyMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
  if (dateOnlyMatch) {
    const [ year, month, day ] = dateOnlyMatch.slice(1).map(Number)
    return new Date(year, month - 1, day)
  }

  return new Date(value)
}

export function formatLocalTime(date, format = "relative", now = new Date()) {
  switch (normalizeFormat(format)) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDate(date, now)
    case "date-year":
      return formatDate(date, now, { includeYear: true })
    case "datetime":
      return formatDateTime(date)
    case "weekday-date":
      return formatWeekdayDate(date)
    case "full":
      return formatFullDateTime(date)
    case "relative":
    default:
      return formatRelativeTime(date, now)
  }
}

export function formatRelativeTime(date, now = new Date()) {
  const differenceInDays = localDayDifference(now, date)

  if (differenceInDays === 0) {
    return formatTime(date)
  } else if (Math.abs(differenceInDays) < RELATIVE_DAYS_WINDOW) {
    return relativeDateFormatter().format(differenceInDays, "day")
  } else {
    return formatDate(date, now)
  }
}

function normalizeFormat(format) {
  return (format || "relative").toString().replaceAll("_", "-")
}

function localDayDifference(fromDate, toDate) {
  return Math.round((beginningOfLocalDay(toDate) - beginningOfLocalDay(fromDate)) / (1000 * 60 * 60 * 24))
}

function beginningOfLocalDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

function formatTime(date) {
  return cleanSpaces(new Intl.DateTimeFormat(LOCALE, {
    hour: "numeric",
    minute: "2-digit"
  }).format(date))
}

function formatDate(date, now = new Date(), { includeYear = date.getFullYear() !== now.getFullYear() } = {}) {
  const options = { month: "short", day: "numeric" }
  options.year = "numeric" if (includeYear)

  return cleanSpaces(new Intl.DateTimeFormat(LOCALE, options).format(date))
}

function formatDateTime(date) {
  return cleanSpaces(new Intl.DateTimeFormat(LOCALE, {
