import { Controller } from "@hotwired/stimulus"
import { formatLocalTime, parseTimestamp } from "helpers/date_helpers"

export default class extends Controller {
  connect() {
    this.#formatAll()
    this.observer = new MutationObserver(this.#handleMutations.bind(this))
    this.observer.observe(this.element, { childList: true, subtree: true })
  }

  disconnect() {
    this.observer?.disconnect()
  }

  #formatAll() {
    this.element.querySelectorAll(".local-time-value[datetime]").forEach(element => this.#format(element))
  }

  #handleMutations(mutations) {
    mutations.forEach(mutation => {
      mutation.addedNodes.forEach(node => this.#formatWithin(node))
    })
  }

  #formatWithin(node) {
    if (node.nodeType !== Node.ELEMENT_NODE) return

    if (node.matches(".local-time-value[datetime]")) {
      this.#format(node)
    }

    node.querySelectorAll(".local-time-value[datetime]").forEach(element => this.#format(element))
  }

  #format(element) {
    const date = parseTimestamp(element.getAttribute("datetime"))
    if (!date || isNaN(date)) return

    element.textContent = formatLocalTime(date, element.dataset.localTimeFormat)
  }
}
